display.text:
import {
  type AtRule,
  type Container,
  type Document,
  type PluginCreator,
  Rule,
} from 'postcss'
import selectorParser from 'postcss-selector-parser'
import { warn } from '../warn'
import { NestedSelectorFrame } from './pluginTrim'

const animationNameRE = /^(-\w+-)?animation-name$/
const animationRE = /^(-\w+-)?animation$/

class ScopedSelectorRewriter {
  private readonly processedRules = new WeakSet<Rule>()

  constructor(private readonly scopeId: string) {}

  rewriteSelector(
    rule: Rule,
    selector?: selectorParser.Selector,
    selectorRoot?: selectorParser.Root,
    ancestorDeep = false,
    slotted = false,
  ): void {
    const frame = new NestedSelectorFrame(rule, ancestorDeep, slotted)
    const cursor = frame.injectCursor()
    const walk = cursor.walkFlags()
    const parent = walk.parentChain()

    if (!selector || !selectorRoot) {
      if (
        this.processedRules.has(rule) ||
        (parent.parentType === 'atrule' &&
          /-?keyframes$/.test(parent.parentName || ''))
      ) {
        return
      }
      this.processedRules.add(rule)
      let deep = false
      let current: Document | Container | undefined = rule.parent
      while (current && current.type !== 'root') {
        if ((current as any).__deep) {
          deep = true
          break
        }
        current = current.parent
      }
      rule.selector = selectorParser(root => {
        root.each(sel => {
          this.rewriteSelector(rule, sel, root, deep)
        })
      }).processSync(rule.selector)
      return
    }

    cursor.shouldInject = !walk.ancestorDeep
    // find the last child node to insert attribute selector
    selector.each(n => {
      // DEPRECATED ">>>" and "/deep/" combinator
      if (
        n.type === 'combinator' &&
        (n.value === '>>>' || n.value === '/deep/')
      ) {
        n.value = ' '
        n.spaces.before = n.spaces.after = ''
        warn(
          `the >>> and /deep/ combinators have been deprecated. ` +
            `Use :deep() instead.`,
        )
        return false
      }

      if (n.type === 'pseudo') {
        const { value } = n
        // deep: inject [id] attribute at the node before the ::v-deep
        // combinator.
        if (value === ':deep' || value === '::v-deep') {
          ;(rule as any).__deep = true
          if (n.nodes.length) {
            // .foo ::v-deep(.bar) -> .foo[xxxxxxx] .bar
            // replace the current node with ::v-deep's inner selector
            let last: selectorParser.Selector['nodes'][0] = n
            n.nodes[0].each(ss => {
              selector.insertAfter(last, ss)
              last = ss
            })
            // insert a space combinator before if it doesn't already have one
            const prev = selector.at(selector.index(n) - 1)
            if (!prev || !isSpaceCombinator(prev)) {
              selector.insertAfter(
                n,
                selectorParser.combinator({
                  value: ' ',
                }),
              )
            }
            selector.removeChild(n)
          } else {
            // DEPRECATED usage
            // .foo ::v-deep .bar -> .foo[xxxxxxx] .bar
            warn(
              `${value} usage as a combinator has been deprecated. ` +
                `Use :deep(<inner-selector>) instead of ${value} <inner-selector>.`,
            )

            const prev = selector.at(selector.index(n) - 1)
            if (prev && isSpaceCombinator(prev)) {
              selector.removeChild(prev)
            }
            selector.removeChild(n)
          }
          return false
        }

        // slot: use selector inside `::v-slotted` and inject [id + '-s']
        // instead.
        // ::v-slotted(.foo) -> .foo[xxxxxxx-s]
        if (value === ':slotted' || value === '::v-slotted') {
          this.rewriteSelector(
            rule,
            n.nodes[0],
            selectorRoot,
            ancestorDeep,
            true /* slotted */,
          )
          let last: selectorParser.Selector['nodes'][0] = n
          n.nodes[0].each(ss => {
            selector.insertAfter(last, ss)
            last = ss
          })
          // selector.insertAfter(n, n.nodes[0])
          selector.removeChild(n)
          // since slotted attribute already scopes the selector there's no
          // need for the non-slot attribute.
          cursor.shouldInject = false
          return false
        }

        // global: replace with inner selector and do not inject [id].
        // ::v-global(.foo) -> .foo
        if (value === ':global' || value === '::v-global') {
          selectorRoot.insertAfter(selector, n.nodes[0])
          selectorRoot.removeChild(selector)
          return false
        }
      }

      if (n.type === 'universal') {
        const prev = selector.at(selector.index(n) - 1)
        const next = selector.at(selector.index(n) + 1)
        // * ... {}
        if (!prev) {
          // * .foo {} -> .foo[xxxxxxx] {}
          if (next) {
            if (next.type === 'combinator' && next.value === ' ') {
              selector.removeChild(next)
            }
            selector.removeChild(n)
            return
          } else {
            // * {} -> [xxxxxxx] {}
            cursor.node = selectorParser.combinator({
              value: '',
            })
            selector.insertBefore(n, cursor.node)
            selector.removeChild(n)
            return false
          }
        }
        // .foo * -> .foo[xxxxxxx] *
        if (cursor.node) return
      }

      if (
        (n.type !== 'pseudo' && n.type !== 'combinator') ||
        (n.type === 'pseudo' &&
          (n.value === ':is' || n.value === ':where') &&
          !cursor.node)
      ) {
        cursor.node = n
      }
    })

    if (frame.nodes.some(node => node.type === 'rule')) {
      const deep = frame.deep
      const decls = frame.nodes.filter(node => node.type === 'decl')
      if (!deep && decls.length) {
        for (const decl of decls) {
          rule.removeChild(decl)
        }
        const hostRule = new Rule({
          nodes: decls,
          selector: '&',
        })
        rule.prepend(hostRule)
      }
      cursor.shouldInject = deep
    }

    if (cursor.node) {
      const { type, value } = cursor.node
      if (type === 'pseudo' && (value === ':is' || value === ':where')) {
        ;(cursor.node as selectorParser.Pseudo).nodes.forEach(value =>
          this.rewriteSelector(
            rule,
            value,
            selectorRoot,
            ancestorDeep,
            slotted,
          ),
        )
        cursor.shouldInject = false
      }
    }

    if (cursor.node) {
      cursor.node.spaces.after = ''
    } else {
      // For deep selectors & standalone pseudo selectors,
      // the attribute selectors are prepended rather than appended.
      // So all leading spaces must be eliminated to avoid problems.
      selector.first.spaces.before = ''
    }

    if (cursor.shouldInject) {
      const idToAdd = cursor.slotted ? this.scopeId + '-s' : this.scopeId
      selector.insertAfter(
        // If node is null it means we need to inject [id] at the start
        // insertAfter can handle `null` here
        cursor.node as any,
        selectorParser.attribute({
          attribute: idToAdd,
          value: idToAdd,
          raws: {},
          quoteMark: `"`,
        }),
      )
    }
  }
}

const scopedPlugin: PluginCreator<string> = (id = '') => {
  const keyframes = Object.create(null)
  const shortId = id.replace(/^data-v-/, '')
  const rewriter = new ScopedSelectorRewriter(id)

  return {
    postcssPlugin: 'vue-sfc-scoped',
    Rule(rule) {
      rewriter.rewriteSelector(rule)
    },
    AtRule(node) {
      if (
        /-?keyframes$/.test(node.name) &&
        !node.params.endsWith(`-${shortId}`)
      ) {
        // register keyframes
        keyframes[node.params] = node.params = node.params + '-' + shortId
      }
    },
    OnceExit(root) {
      if (Object.keys(keyframes).length) {
        // If keyframes are found in this <style>, find and rewrite animation names
        // in declarations.
        // Caveat: this only works for keyframes and animation rules in the same
        // <style> element.
        // individual animation-name declaration
        root.walkDecls(decl => {
          if (animationNameRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => keyframes[v.trim()] || v.trim())
              .join(',')
          }
          // shorthand
          if (animationRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => {
                const vals = v.trim().split(/\s+/)
                const i = vals.findIndex(val => keyframes[val])
                if (i !== -1) {
                  vals.splice(i, 1, keyframes[vals[i]])
                  return vals.join(' ')
                } else {
                  return v
                }
              })
              .join(',')
          }
        })
      }
    },
  }
}

function isSpaceCombinator(node: selectorParser.Node) {
  return node.type === 'combinator' && /^\s+$/.test(node.value)
}

scopedPlugin.postcss = true
export default scopedPlugin

