import type { ChildNode, PluginCreator, Rule } from 'postcss'
import { SelectorInjectCursor } from './cssVars'

export class NestedSelectorFrame {
  readonly cursor: SelectorInjectCursor
  constructor(
    private readonly rule: Rule,
    ancestorDeep: boolean,
    slotted = false,
  ) {
    this.cursor = new SelectorInjectCursor(rule, ancestorDeep, slotted)
  }
  injectCursor(): SelectorInjectCursor {
    return this.cursor
  }
  get nodes(): ChildNode[] {
    return this.rule.nodes
  }
  get deep(): boolean {
    return !!(this.rule as any).__deep
  }
}

const trimPlugin: PluginCreator<{}> = () => {
  return {
    postcssPlugin: 'vue-sfc-trim',
    Once(root) {
      root.walk(({ type, raws }) => {
        if (type === 'rule' || type === 'atrule') {
          if (raws.before) raws.before = '\n'
          if ('after' in raws && raws.after) raws.after = '\n'
        }
      })
    },
  }
}

trimPlugin.postcss = true
export default trimPlugin

