input.newString:
AtRule(node) {
  if (
    /-?keyframes$/.test(node.name) &&
    !node.params.endsWith(`-${shortId}`)
  ) {
    // register keyframes
    keyframes[node.params] = node.params = node.params + '-' + shortId
  } else if (node.nodes && hasAncestorRule(node)) {
    // declarations directly inside a nested at-rule need to be wrapped
    // in a nesting selector so that they can be scoped.
    const nodes = node.nodes.filter(
      n => n.type !== 'rule' && n.type !== 'atrule',
    )
    if (nodes.some(n => n.type === 'decl')) {
      for (const n of nodes) {
        node.removeChild(n)
      }
      node.prepend(
        new Rule({
          nodes,
          selector: '&',
        }),
      )
    }
  }
},

